import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.DtFGJNng.js";const p=JSON.parse('{"title":"UI design","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/ui-design.md","filePath":"artifacts/ui-design.md","lastUpdated":1794463556000}'),r={name:"artifacts/ui-design.md"};function s(d,a,u,o,l,k){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ui-design" tabindex="-1">UI design <a class="header-anchor" href="#ui-design" aria-label="Permalink to &quot;UI design&quot;">​</a></h1><p><strong>Owner:</strong> designer · <strong>Bergantung pada:</strong> specs · <strong>Di-skip bila:</strong> area <code>design</code> tidak terdampak · <strong>Dibaca oleh:</strong> backend dan frontend (untuk menyepakati kontrak), frontend (untuk membangun), qa (untuk menguji).</p><h2 id="untuk-apa" tabindex="-1">Untuk apa <a class="header-anchor" href="#untuk-apa" aria-label="Permalink to &quot;Untuk apa&quot;">​</a></h2><p>Layar-layar yang menampilkan perilaku di specs, ditambah satu indeks (<code>ui-design/README.md</code>) yang menghubungkan layar-layar itu dengan specs dan test.</p><h2 id="indeks" tabindex="-1">Indeks <a class="header-anchor" href="#indeks" aria-label="Permalink to &quot;Indeks&quot;">​</a></h2><p>Untuk setiap layar: file di dalam work, path tujuan di design home, dan apakah layar itu baru, berubah, atau tidak berubah (hanya dirujuk). Untuk setiap layar baru atau berubah: requirement yang dicakup, state-nya (default, kosong, loading, error, akses ditolak, layar kecil, dan state lain yang tersirat dari scenario), serta teks yang terlihat dan diandalkan test.</p><h2 id="aturan" tabindex="-1">Aturan <a class="header-anchor" href="#aturan" aria-label="Permalink to &quot;Aturan&quot;">​</a></h2><ul><li>Kerjakan salinan di dalam work. Design home harus tetap sesuai dengan yang sudah dibangun sampai frontend mem-promote design baru bersama kodenya.</li><li>Design menampilkan perilaku dari specs; design tidak menambah perilaku. Butuh aturan baru? Ubah specs dulu.</li></ul><h2 id="pelajaran" tabindex="-1">Pelajaran <a class="header-anchor" href="#pelajaran" aria-label="Permalink to &quot;Pelajaran&quot;">​</a></h2><ul><li><strong>Gambar state-nya, bukan hanya alur sukses.</strong> State loading, error, dan &quot;aksi gagal&quot; yang tidak didesain akan dikarang saat implementasi, dan design tidak pernah lagi sama dengan produknya.</li><li><strong>Design yang tidak diperbarui saat produk berubah berhenti menjadi rujukan.</strong> Langkah promote ada supaya design dan kode masuk ke design home bersamaan.</li><li><strong>Cantumkan tujuan navigasi</strong> (ke mana setiap link mengarah). Itu perilaku, dan ia bergeser kalau tidak ada yang memilikinya.</li></ul>',10)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
